const payloadString = inputData.webhook_payload || '{}';

let payload;
try {
  payload = typeof payloadString === 'object' ? payloadString : JSON.parse(payloadString);
} catch (e) {
  return {
    is_valid: false,
    full_name: '',
    email: '',
    company: '',
    job_title: '',
    source: '',
    interested_in: '',
    message: '',
    validation_error: 'Invalid JSON payload'
  };
}

// Extract fields and clean trailing/leading spaces
const full_name = (payload.full_name || '').trim();
const email = (payload.email || '').trim();
const company = (payload.company || '').trim();
const job_title = (payload.job_title || '').trim();
const source = (payload.source || '').trim();
const interested_in = (payload.interested_in || '').trim();
const message = (payload.message || '').trim();

const errors = [];

// 1. Full Name: Must contain at least first and last name
const nameParts = full_name.split(/\s+/).filter(Boolean);
if (!full_name) {
  errors.push('full_name is required and cannot be empty');
} else if (nameParts.length < 2) {
  errors.push('full_name must include both first and last name (e.g., Ali Khan)');
}

// 2. Email: Must contain @ and a domain
if (!email) {
  errors.push('email is required and cannot be empty');
} else if (!email.includes('@') || !email.includes('.')) {
  errors.push('email must contain a valid format with @ and a domain');
}

// 3. Company: Compulsory
if (!company) {
  errors.push('company is required and cannot be empty');
}

// 4. Job Title: Compulsory
if (!job_title) {
  errors.push('job_title is required and cannot be empty');
}

// 5. Source: Must be one of Website, LinkedIn, Referral, Advertisement
const allowedSources = ['Website', 'LinkedIn', 'Referral', 'Advertisement'];
if (!source) {
  errors.push('source is required and cannot be empty');
} else if (!allowedSources.some(item => item.toLowerCase() === source.toLowerCase())) {
  errors.push(`source must be one of: ${allowedSources.join(', ')}`);
}

// 6. Interested In: Must be one of Web Development, Automation, AI Solutions, Other
const allowedInterests = ['Web Development', 'Automation', 'AI Solutions', 'Other'];
if (!interested_in) {
  errors.push('interested_in is required and cannot be empty');
} else if (!allowedInterests.some(item => item.toLowerCase() === interested_in.toLowerCase())) {
  errors.push(`interested_in must be one of: ${allowedInterests.join(', ')}`);
}

// 7. Message: Compulsory
if (!message) {
  errors.push('message is required and cannot be empty');
}

// Final Validation Result
const is_valid = errors.length === 0;

return {
  is_valid,
  full_name,
  email,
  company,
  job_title,
  source,
  interested_in,
  message,
  validation_error: is_valid ? '' : errors.join('; ')
};

const cleaned = inputData.raw_text.replace(/```json/g, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleaned);

output = {
  ai_category: parsed.ai_category,
  priority: parsed.priority,
  ai_reason: parsed.ai_reason,
  status: parsed.status,
  assigned_team: parsed.assigned_team,
  follow_up: parsed.follow_up
};

